export function detectCategory(businessType) {
    const normalizedInput = (businessType || "").toLowerCase().trim();
    // 1. Direct key match
    for (const key of Object.keys(CATEGORIES_DATA)) {
        if (normalizedInput === key.toLowerCase()) {
            return CATEGORIES_DATA[key];
        }
    }
    // 2. Keyword/Sub-string match
    for (const key of Object.keys(CATEGORIES_DATA)) {
        const keyLower = key.toLowerCase();
        if (normalizedInput.includes(keyLower) || keyLower.includes(normalizedInput)) {
            return CATEGORIES_DATA[key];
        }
    }
    // Common keywords map to specific templates
    if (normalizedInput.includes("bakery") || normalizedInput.includes("cake") || normalizedInput.includes("bread") || normalizedInput.includes("pastry") || normalizedInput.includes("sweet")) {
        return CATEGORIES_DATA["Bakery"];
    }
    if (normalizedInput.includes("restaurant") || normalizedInput.includes("dine") || normalizedInput.includes("kitchen") || normalizedInput.includes("food") || normalizedInput.includes("dhaba")) {
        return CATEGORIES_DATA["Restaurant"];
    }
    if (normalizedInput.includes("cafe") || normalizedInput.includes("coffee") || normalizedInput.includes("brew")) {
        return CATEGORIES_DATA["Cafe"];
    }
    if (normalizedInput.includes("clothing") || normalizedInput.includes("wear") || normalizedInput.includes("garment") || normalizedInput.includes("tailor") || normalizedInput.includes("boutique")) {
        return CATEGORIES_DATA["Fashion Boutique"];
    }
    if (normalizedInput.includes("jewelry") || normalizedInput.includes("gold") || normalizedInput.includes("silver") || normalizedInput.includes("diamond")) {
        return CATEGORIES_DATA["Jewelry Store"];
    }
    if (normalizedInput.includes("salon") || normalizedInput.includes("parlour") || normalizedInput.includes("barber") || normalizedInput.includes("hair")) {
        return CATEGORIES_DATA["Salon"];
    }
    if (normalizedInput.includes("spa") || normalizedInput.includes("massage") || normalizedInput.includes("therapy")) {
        return CATEGORIES_DATA["Spa"];
    }
    if (normalizedInput.includes("gym") || normalizedInput.includes("fitness") || normalizedInput.includes("workout") || normalizedInput.includes("sports") || normalizedInput.includes("academy")) {
        return CATEGORIES_DATA["Gym"];
    }
    if (normalizedInput.includes("medical") || normalizedInput.includes("clinic") || normalizedInput.includes("dentist") || normalizedInput.includes("doctor") || normalizedInput.includes("pharmacy")) {
        return CATEGORIES_DATA["Clinic"];
    }
    if (normalizedInput.includes("elect") || normalizedInput.includes("mobile") || normalizedInput.includes("computer") || normalizedInput.includes("tech") || normalizedInput.includes("phone")) {
        return CATEGORIES_DATA["Electronics Store"];
    }
    // 3. Fallback: Local Retail Shop
    return CATEGORIES_DATA["Local Retail Shop"];
}
